122	// Defensive cleanup of client-supplied attachments. Drops anything with a
123	// malformed hash / bad mime; preserves order and metadata of valid items.
124	// Hard cap of 6 — matches spec's per-node limit; further trimming the
125	// client missed is harmless rather than a hard fail.
126	function sanitizeAttachments(raw: unknown): NodeAttachment[] {
127	  if (!Array.isArray(raw)) return [];
128	  const out: NodeAttachment[] = [];
129	  for (const item of raw) {
130	    if (!item || typeof item !== "object") continue;
131	    const a = item as Record<string, unknown>;
132	    if (typeof a.hash !== "string" || !isValidHash(a.hash)) continue;
133	    if (typeof a.mime !== "string" || !isKnownAttachmentMime(a.mime)) continue;
134	    if (typeof a.size !== "number") continue;
135	    out.push({
136	      hash: a.hash,
137	      mime: a.mime,
138	      size: a.size,
139	      filename: typeof a.filename === "string" ? a.filename : null,
140	      width: typeof a.width === "number" ? a.width : undefined,
141	      height: typeof a.height === "number" ? a.height : undefined,
142	    });
143	    if (out.length >= 6) break;
144	  }
145	  return out;
146	}
