148	// Resolve NodeAttachment[] (hash refs) to provider-ready {path, mime}.
149	// Drops items whose blob is missing on disk (rare but possible if the
150	// blobs dir got wiped between upload and submit).
151	function resolveAttachments(
152	  attachments: NodeAttachment[],
153	): { path: string; mime: string }[] {
154	  const resolved: { path: string; mime: string }[] = [];
155	  for (const a of attachments) {
156	    const r = resolveBlobPath(a.hash);
157	    if (r) resolved.push(r);
158	  }
159	  return resolved;
160	}
