162	// Pure-chat inline cap for text attachments. ~32k tokens worst case —
163	// big enough for real CSV/log samples, small enough to not blow the
164	// context window on a single file.
165	const INLINE_CAP_BYTES = 128 * 1024;
166	
167	function fmtSize(n: number): string {
168	  if (n < 1024) return `${n} B`;
169	  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
170	  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
171	}
