173	// Generic (non-image) attachments reach the model as prompt text, shaped
174	// by what the mode can do:
175	//  - tool-capable (project / enhanced chat): stage blobs to
176	//    ~/.trellis/uploads/<nodeId>/ under their original filenames and list
177	//    absolute paths — the agent reads/parses them with its own tools.
178	//  - pure chat (web tools only): inline text files bodily (≤ cap); note
179	//    anything unreadable so the model doesn't hallucinate the content.
180	// Staging is idempotent per nodeId, so retry (which re-reads attachments
181	// from the DB) rebuilds the exact same paths.
182	function buildFileAttachmentSuffix(
183	  nodeId: string,
184	  files: NodeAttachment[],
185	  toolCapable: boolean,
186	): string {
187	  if (files.length === 0) return "";
188	  if (toolCapable) {
189	    const staged = materializeAttachments(nodeId, files);
190	    if (staged.length === 0) return "";
191	    const lines = staged.map(
192	      (s) => `- ${s.path}（${s.mime}, ${fmtSize(s.size)}）`,
193	    );
194	    return `\n\n[用户上传的附件文件，已保存在本地磁盘，可直接用 Read / Bash 等工具读取：]\n${lines.join("\n")}`;
195	  }
196	  const parts: string[] = [];
197	  for (const f of files) {
198	    const name = f.filename ?? `file-${f.hash.slice(0, 8)}`;
199	    const text = isTextMime(f.mime)
200	      ? readTextBlob(f.hash, INLINE_CAP_BYTES)
201	      : null;
202	    if (text !== null) {
203	      // Four-backtick fence so embedded ``` in the file body can't
204	      // break out of the block.
205	      parts.push(
206	        `文件「${name}」（${f.mime}）的完整内容：\n\`\`\`\`\n${text}\n\`\`\`\``,
207	      );
208	    } else {
209	      const reason = isTextMime(f.mime)
210	        ? "超过内联大小上限"
211	        : "二进制文件需要文件工具";
212	      parts.push(
213	        `文件「${name}」（${f.mime}, ${fmtSize(f.size)}）已上传，但纯对话模式无法读取（${reason}）——请提醒用户改用增强模式 / Project 再问。`,
214	      );
215	    }
216	  }
217	  return `\n\n[用户上传的附件]\n${parts.join("\n\n")}`;
218	}
