534	    const branchFrom = body.parentNodeId;
535	    const lin = attachedLineageForNode(branchFrom);
536	    if (lin) {
537	      attachedHandled = true;
538	      if (lin.isJsonlTip && !hasOtherChild(branchFrom, nodeId)) {
539	        claudeSessionId = lin.lineageSid; // 线性续：--resume 同 lineage，append 同 jsonl
540	      } else {
541	        const built = buildPrefixJsonl(branchFrom); // 任意点分叉
542	        if (built) {
543	          registerForkLineage(
544	            trellisSessionId,
545	            built.newSid,
546	            built.jsonlPath,
547	            branchFrom, // fork_point = X turn uuid
548	          );
549	          // 新节点归属新 fork lineage（reconcile 删临时节点后 canonical 会重得同值）。
550	          setNodeResumeId(nodeId, family, built.newSid);
551	          claudeSessionId = built.newSid;
552	        } else {
553	          claudeSessionId = lin.lineageSid; // 构造失败兜底线性
554	        }
555	      }
556	    }
557	  }
558	  if (
559	    resolvedOrigin === "cli-import" &&
560	    body.kind === "branch" &&
561	    family === "codex"
562	  ) {
563	    const branchFrom = body.parentNodeId;
564	    const lin = codexLineageForNode(branchFrom);
565	    if (lin) {
566	      attachedHandled = true;
567	      if (lin.isRolloutTip && !hasOtherChild(branchFrom, nodeId)) {
568	        claudeSessionId = lin.lineageSid;
569	      } else if (lin.nodeTurnOrdinal) {
570	        const built = buildCodexPrefixRollout(lin.rolloutPath, lin.nodeTurnOrdinal);
571	        if (built) {
572	          registerForkLineage(
573	            trellisSessionId,
574	            built.newSid,
575	            built.rolloutPath,
576	            branchFrom,
577	            "codex",
578	          );
579	          setNodeResumeId(nodeId, family, built.newSid);
580	          claudeSessionId = built.newSid;
581	        } else {
582	          claudeSessionId = lin.lineageSid;
583	        }
584	      } else {
585	        claudeSessionId = lin.lineageSid;
586	      }
587	    }
588	  }
589	  // 原生 per-lineage 隔离（progress/project-lineage-isolation-spec.md）：新建的
590	  // project session（lineage_isolation=1）走 lineage 解析，路由与 attached P2 同构：
591	  // 父是 lineage jsonl tip 且无其他子 → 线性 resume 该 lineage（append 同 jsonl）；
592	  // 真分叉 → 前缀 jsonl 在父 turn 分叉成新 lineage；uuid 缺失/构造失败 → 降级线性
593	  // （= 旧共享行为，上下文只多不错）。root/新话题 → fresh，sid 由 session_init 落
594	  // 本节点（lineage 头自持）。仅 claude family；存量 session（flag=0）与 codex 走
595	  // 下方旧路径。
596	  let nativeIsolated = false;
597	  if (
598	    !attachedHandled &&
599	    mode === "project" &&
600	    family === "claude" &&
601	    resolvedOrigin === "native" &&
602	    isLineageIsolated(trellisSessionId)
603	  ) {
604	    nativeIsolated = true;
605	    if (body.kind === "branch") {
606	      const lin = nativeLineageForNode(body.parentNodeId, spawnCwd);
607	      if (!lin) {
608	        // 祖先链无可用 lineage（首轮失败 / jsonl 被清）→ fresh，本节点成新 lineage 头。
609	        claudeSessionId = null;
610	      } else if (lin.isJsonlTip && !hasOtherChild(body.parentNodeId, nodeId)) {
611	        claudeSessionId = lin.lineageSid;
612	      } else if (lin.nodeTurnUuid) {
613	        const built = buildPrefixJsonlCore(lin.jsonlPath, lin.nodeTurnUuid);
614	        if (built) {
615	          // 新 lineage 头预写 sid（trellis 同步生成，不依赖 session_init）。
616	          setNodeResumeId(nodeId, family, built.newSid);
617	          claudeSessionId = built.newSid;
618	        } else {
619	          claudeSessionId = lin.lineageSid;
620	        }
621	      } else {
622	        claudeSessionId = lin.lineageSid;
623	      }
624	    } else if (body.kind === "retry") {
625	      // self-or-ancestor：fork 头重试续自己的 lineage，线性节点续父 lineage；
626	      // jsonl 缺失 → null → fresh + sid 落本节点（自愈，同 claudeJsonlExists 纪律）。
627	      const lin = nativeLineageForNode(nodeId, spawnCwd);
628	      claudeSessionId = lin?.lineageSid ?? null;
629	    } else {
630	      claudeSessionId = null; // root / 新话题：fresh lineage
631	    }
632	  }
633	  // codex 版 per-lineage 隔离：与上面 claude 块同构，engine 换 codex-fork
634	  // （rollout 无 uuid 链，下刀坐标 = user-message 序号）。存量 codex project
635	  // （iso=0）不迁移，走下方旧路径（全树共享 root rollout）。retry 与 claude 同
636	  // 纪律：线性 resume 自己/祖先的 lineage（旧回答留在 rollout，上下文只多不错）。
637	  if (
638	    !attachedHandled &&
639	    !nativeIsolated &&
640	    mode === "project" &&
641	    family === "codex" &&
642	    resolvedOrigin === "native" &&
643	    isLineageIsolated(trellisSessionId)
644	  ) {
645	    nativeIsolated = true;
646	    if (body.kind === "branch") {
647	      const lin = codexLineageForNode(body.parentNodeId);
648	      if (!lin) {
649	        claudeSessionId = null; // 祖先链无可用 lineage → fresh，本节点成新头
650	      } else if (lin.isRolloutTip && !hasOtherChild(body.parentNodeId, nodeId)) {
651	        claudeSessionId = lin.lineageSid;
652	      } else if (lin.nodeTurnOrdinal) {
653	        const built = buildCodexPrefixRollout(lin.rolloutPath, lin.nodeTurnOrdinal);
654	        if (built) {
655	          setNodeResumeId(nodeId, family, built.newSid);
656	          claudeSessionId = built.newSid;
657	        } else {
658	          claudeSessionId = lin.lineageSid;
659	        }
660	      } else {
661	        claudeSessionId = lin.lineageSid;
662	      }
663	    } else if (body.kind === "retry") {
664	      const lin = codexLineageForNode(nodeId);
665	      claudeSessionId = lin?.lineageSid ?? null;
666	    } else {
667	      claudeSessionId = null; // root / 新话题：fresh lineage
668	    }
669	  }
670	  if (!attachedHandled && !nativeIsolated) {
671	    claudeSessionId =
672	      mode === "project"
673	        ? getRootResumeIdForNode(nodeId, family, spawnCwd)
674	        : chatBFork
675	          ? getParentResumeId(nodeId, family, spawnCwd)
676	          : codexChatHandled
677	            ? codexChatSid
678	            : null;
679	  }
680	
681	  // S88 @提及：外援是**一次性**的 —— 覆盖掉上面那整套身份解析。
682	  //   · 不 resume 主线：外援的人设写进主线 CLI session 会永久污染主线人格；
683	  //   · 不 fork：会在 cwd 的 jsonl 目录留一个孤儿 session，让 nativeLineageForNode
684	  //     的簿记认错 tip（这是 cli-fork 那套最脆的地方）；
685	  //   · 不落盘（ephemeral）：外援看一眼就走，不该在 resume 链上留痕。
686	  // 上下文靠折叠历史 —— 复用已有的降级路径，零新代码。
687	  if (mentionActive) {
688	    claudeSessionId = null;
689	    chatBFork = false;
690	    if (history.length === 0) {
691	      history = buildHistoryForNode(nodeId, { maxDepth: 4 });
692	    }
693	  }
694	
695	  // Stage 17: spawn ownership now lives in run-bus, not this handler.
696	  // We start the run with its own AbortController; HTTP disconnect only
697	  // unsubscribes us from the event broadcast — the LLM keeps running and
698	  // keeps writing to the DB. Late tabs / a returning mobile client pick
699	  // up via GET /api/nodes/[id]/stream.
700	  // A路②: claude speaks the stdio permission protocol (interactive tools
701	  // AskUserQuestion / ExitPlanMode + approve-mode cards). codex (agent@0.7.0)
702	  // rides the app-server approval RPCs mapped to the same onCanUseTool shape —
703	  // approve 模式下 commandExecution/fileChange 弹权限卡；非 approve 模式回调闲置
704	  // (approvalPolicy=never，codex 无 AskUserQuestion 等价物)。mock has neither.
705	  // Pure chat (no workspace) won't trigger cards; threading the callback is
706	  // harmless there.
707	  const interactive = family === "claude" || family === "codex";
708	  // S88: 把 agent 定义变成「CLI 能吃的东西」。放在 route 而不是 sdk-adapter：
709	  // 后者至今是纯函数无 IO，且被 codex 共用；route 本就是策略解析层
710	  // （mode / workspace / resume / approval 都在这儿定）。
711	  // agent 被停用 / 被删 → resolveEnabledAgent 返回 null → 静默退回默认人设，
712	  // 绝不让「人设没了」变成「会话发不出消息」。
713	  // @提及优先于会话人设：这一轮是外援答的。
714	  const agentRecord = mentionActive ? mentionAgent : resolveEnabledAgent(resolvedAgentId);
715	  const agentSpawn = agentRecord && family !== "mock"
716	    ? resolveAgentSpawn(agentRecord, family, resolvedWorkspacePath)
717	    : null;
718	  // 每轮落一份「谁答的」。会话级也记 —— agent 定义是 live 引用（改了老会话跟着变），
719	  // 这一列是事后唯一能追溯「当时哪个 agent 答的」的线索。
720	  if (agentRecord) {
721	    setNodeAgent(nodeId, agentRecord.id, mentionActive ? "mention" : "session");
722	  }
723	  startRun({
724	    nodeId,
725	    // chat B-fork writes the forked id to THIS node (per-node); native isolated
726	    // project writes the fresh lineage head's id to THIS node (fork heads were
727	    // pre-written above, so claudeSessionId is set → undefined); legacy project
728	    // writes the root-shared id on its first turn only; codex/mock/window
729	    // persist none.
730	    sessionIdTarget: attachedHandled
731	      ? undefined
732	      : nativeIsolated
733	        ? claudeSessionId
734	          ? undefined
735	          : "node"
736	        : chatBFork || codexChatHandled
737	          ? "node"
738	          : mode === "project"
739	            ? claudeSessionId
740	              ? undefined
741	              : "root"
742	            : undefined,
743	    resumeFamily: family,
744	    interactive,
745	    requireApproval: resolvedRequireApproval,
746	    factory: (signal, ctx) =>
747	      llm.stream({
748	        history,
749	        question: questionForLLM,
750	        parentAnchor,
751	        signal,
752	        claudeSessionId,
753	        cwd: spawnCwd,
754	        systemPrompt: resolvedSystemPrompt,
755	        agent: agentSpawn,
756	        // @提及：一次性 spawn，不落盘不 resume（见上方 mentionActive 那段）。
757	        ephemeral: mentionActive,
758	        chatEnhanced,
759	        // claude B-fork 与 codex chat resume 共用这面旗：sdk-adapter 据此开
760	        // persistence+resume（--fork-session 本身 codex backend 会忽略）。
761	        forkSession: chatBFork || codexChatHandled,
762	        requireApproval: resolvedRequireApproval,
763	        attachments: providerAttachments,
764	        onCanUseTool: ctx?.onCanUseTool,
765	      }),
766	    topicLabel:
767	      providerId !== "mock"
768	        ? (aggregated) => generateTopicLabel(questionForTopic, aggregated, family)
769	        : undefined,
770	    // 自动命名（体验 D）：首答完成起一次题，此后每 8 个完成节点按最近几轮
771	    // 刷新「当前主题」。判定全走 DB（origin 只认 native —— attach/import 的
772	    // 标题归 importer/watcher 管；title_source='user' 永不覆盖）。mock 跳过，
773	    // 与 topicLabel 同因：测试路径不该 spawn CLI。
774	    sessionTitle:
775	      providerId !== "mock"
776	        ? async () => {
777	            const ctx = getSessionTitleContext(trellisSessionId);
778	            if (!ctx || ctx.origin !== "native" || ctx.titleSource === "user") {
779	              return null;
780	            }
781	            const due =
782	              ctx.doneCount === 1 ||
783	              (ctx.doneCount > 1 && ctx.doneCount % 8 === 0);
784	            if (!due || ctx.turns.length === 0) return null;
785	            const title = await generateSessionTitle(ctx.turns, family);
786	            if (!title || !applyAutoTitle(trellisSessionId, title)) return null;
787	            return { sessionId: trellisSessionId, title };
788	          }
789	        : undefined,
790	  });
791	
792	  const encoder = new TextEncoder();
793	  const stream = new ReadableStream({
794	    start(controller) {
795	      let closed = false;
796	      const send = (event: Record<string, unknown>) => {
797	        if (closed) return;
798	        try {
799	          controller.enqueue(
800	            encoder.encode(`data: ${JSON.stringify(event)}\n\n`),
801	          );
802	        } catch {
803	          closed = true;
804	        }
805	      };
806	      const close = () => {
807	        if (closed) return;
808	        closed = true;
809	        try {
810	          controller.close();
811	        } catch {
812	          /* already closed */
813	        }
814	      };
815	
816	      // The bus doesn't know about session/node entities — the first
817	      // event the client sees is still the `created` payload assembled
818	      // up here. After that, live RunEvents flow through.
819	      send(createdEvent);
820	
821	      const unsubscribe = subscribe(nodeId, {
822	        onEvent: (event) => {
823	          // Suppress catchup for the freshly-started run — the client
824	          // already has the node row (empty response) from `created`,
825	          // and the catchup payload would always be "" for the first
826	          // subscriber anyway. Reconnect endpoints DO forward catchup;
827	          // see GET /api/nodes/[id]/stream.
828	          if (event.type === "catchup") return;
829	          send(event);
830	        },
831	        onClose: close,
832	      });
833	      if (!unsubscribe) {
834	        // Shouldn't happen — we just startRun'd. Defensive close.
835	        close();
836	        return;
837	      }
838	
839	      // HTTP disconnect: drop our subscription, but let the run continue.
840	      // Explicit abort goes through POST /api/chat/[id]/abort, not the
841	      // request signal.
842	      const onAbort = () => {
843	        unsubscribe();
844	        close();
845	      };
846	      if (req.signal.aborted) {
847	        onAbort();
848	      } else {
849	        req.signal.addEventListener("abort", onAbort, { once: true });
850	      }
851	    },
852	  });
853	
854	  return new Response(stream, {
855	    headers: {
856	      "Content-Type": "text/event-stream; charset=utf-8",
857	      "Cache-Control": "no-cache, no-transform",
858	      Connection: "keep-alive",
859	      "X-Accel-Buffering": "no",
860	    },
861	  });
862	}
