13	import { codexLineageForNode } from "./codex-fork";
14	// jsonl 读取与 turn 归属全部走 ./cli-jsonl —— 与 cli-import 同一份实现。
15	// 这里曾经有一套自己抄的副本（userText / isToolResultEntry / isCommandNoise /
16	// isTurnStart / ms），import 侧后来长出 5 道结构闸而这份没跟，导致 fork 在一条
17	// 自己认不出边界的 turn 上截前缀。事故与实测数字记在 ./cli-jsonl 头部。
18	import {
19	  type CliRawEntry,
