21	  readJsonlLines,
22	  terminalAssistantLine,
23	} from "./cli-jsonl";
24	import { providerFamily, DEFAULT_PROVIDER } from "@/lib/llm";
25	
26	export type AttachedLineage = {
27	  lineageSid: string;
28	  sourceJsonlPath: string;
29	  isJsonlTip: boolean;
30	};
31	
32	function newestTurnId(jsonlPath: string): string | null {
33	  const parsed = parseCliSessionJsonl(jsonlPath);
34	  if (!parsed || parsed.turns.length === 0) return null;
35	  return [...parsed.turns].sort(
36	    (a, b) => b.createdAt - a.createdAt || b.id.localeCompare(a.id),
