39	
40	export function attachedLineageForNode(nodeId: string): AttachedLineage | null {
41	  const db = getDB();
42	  const node = db
43	    .prepare(
44	      `SELECT n.id, n.session_id, n.parent_id, n.claude_session_id, s.origin
45	       FROM nodes n
46	       JOIN sessions s ON s.id = n.session_id
47	       WHERE n.id = ?`,
48	    )
49	    .get(nodeId) as
50	    | {
51	        id: string;
52	        session_id: string;
53	        parent_id: string | null;
54	        claude_session_id: string | null;
55	        origin: string;
56	      }
57	    | undefined;
58	  if (!node || node.origin !== "cli-import") return null;
59	
60	  let lineageSid = node.claude_session_id;
61	  let parentId = node.parent_id;
62	  const parentStmt = db.prepare(
63	    "SELECT parent_id, claude_session_id FROM nodes WHERE id = ?",
64	  );
65	  while (!lineageSid && parentId) {
66	    const parent = parentStmt.get(parentId) as
67	      | { parent_id: string | null; claude_session_id: string | null }
68	      | undefined;
69	    if (!parent) break;
70	    lineageSid = parent.claude_session_id;
71	    parentId = parent.parent_id;
72	  }
73	  if (!lineageSid) return null;
74	
75	  const row = db
76	    .prepare(
77	      `SELECT jsonl_path
78	       FROM cli_lineages
79	       WHERE trellis_session_id = ? AND cli_session_id = ?
80	         AND provider_family = 'claude'`,
81	    )
82	    .get(node.session_id, lineageSid) as { jsonl_path: string } | undefined;
83	  if (!row) return null;
84	
85	  const tipId = newestTurnId(row.jsonl_path);
86	  if (!tipId) return null;
87	  return {
88	    lineageSid,
89	    sourceJsonlPath: row.jsonl_path,
90	    isJsonlTip: tipId === nodeId,
91	  };
92	}
93	
94	// 「在 CLI 继续」轻量入口（progress/cli-branch-alignment.md §7）：project 模式会话
95	// 本就是真 claude CLI 会话——给出在 CLI 续该节点 lineage 的 cwd + resume id。
96	// attached（cli-import）取该节点的 lineage sid（验源 jsonl 在盘）；native project 走
97	// getRootResumeIdForNode（其自带 jsonl 存在性自愈，缺失返回 null=不可续）。
98	// 仅 project 模式（有 cwd 才可 resume）；chat 返回 null。续到的是该 lineage 的
99	// 主链 tip（CLI --resume 本就只跟主链——树内分叉走 P2 的前缀 jsonl，不在本入口范围）。
100	export function cliResumeForNode(
101	  nodeId: string,
102	): { cwd: string; resumeId: string; family: "claude" | "codex" } | null {
103	  const db = getDB();
104	  const node = db
105	    .prepare("SELECT session_id FROM nodes WHERE id = ?")
106	    .get(nodeId) as { session_id: string } | undefined;
107	  if (!node) return null;
108	  const session = getSession(node.session_id);
109	  if (!session || session.mode !== "project" || !session.workspacePath) {
110	    return null;
111	  }
112	  // codex 系 project：rollout 就是真 codex CLI 会话，出 `codex resume <sid>`。
113	  // attach（cli-import）是 claude 专属域，codex 不会有。
114	  const family = providerFamily(session.model ?? DEFAULT_PROVIDER);
115	  if (family === "codex") {
116	    const resumeId =
117	      session.origin === "cli-import" || isLineageIsolated(session.id)
118	      ? codexLineageForNode(nodeId)?.lineageSid ?? null
119	      : getRootResumeIdForNode(nodeId, "codex", session.workspacePath);
120	    if (!resumeId) return null;
121	    return { cwd: session.workspacePath, resumeId, family: "codex" };
122	  }
123	  if (session.origin === "cli-import") {
124	    const lin = attachedLineageForNode(nodeId);
125	    if (!lin || !fs.existsSync(lin.sourceJsonlPath)) return null;
126	    return { cwd: session.workspacePath, resumeId: lin.lineageSid, family: "claude" };
127	  }
128	  // isolated（per-lineage）native 会话：续到该节点所属 lineage（fork 分支各有
129	  // 自己的 sid，root sid 只覆盖主 lineage）；legacy 会话维持 root sid 旧路径。
130	  if (isLineageIsolated(session.id)) {
131	    const lin = nativeLineageForNode(nodeId, session.workspacePath);
132	    if (!lin) return null;
133	    return { cwd: session.workspacePath, resumeId: lin.lineageSid, family: "claude" };
134	  }
135	  const resumeId = getRootResumeIdForNode(nodeId, "claude", session.workspacePath);
136	  if (!resumeId) return null;
137	  return { cwd: session.workspacePath, resumeId, family: "claude" };
138	}
139	
140	// X 在 trellis 树里是否已有「除了 exceptId 之外」的子节点。续聊时：tip 且无其他子
141	// → 线性 append；否则（非 tip 或已有子）→ 必须分叉，否则会污染该 lineage 的线性 jsonl。
142	export function hasOtherChild(parentId: string, exceptId: string): boolean {
143	  const db = getDB();
144	  const row = db
145	    .prepare(
146	      "SELECT 1 FROM nodes WHERE parent_id = ? AND id != ? LIMIT 1",
147	    )
148	    .get(parentId, exceptId);
149	  return Boolean(row);
150	}
151	
152	// 登记一条 fork lineage（trellis 在 X 分叉造了新 jsonl）。幂等 upsert，与 watcher
153	// 的新 fork 检测共用 cli_lineages 表；is_root=0、synced_uuid=NULL 待首次 import 回填。
154	export function registerForkLineage(
155	  trellisSessionId: string,
156	  newSid: string,
157	  jsonlPath: string,
158	  forkPointUuid: string,
159	  provider: "claude" | "codex" = "claude",
160	): void {
161	  const db = getDB();
162	  db.prepare(
163	    `INSERT INTO cli_lineages
164	       (trellis_session_id, cli_session_id, provider_family, jsonl_path,
165	        fork_point_uuid, is_root, synced_uuid)
166	     VALUES (?, ?, ?, ?, ?, 0, NULL)
167	     ON CONFLICT(trellis_session_id, cli_session_id) DO UPDATE SET
168	       provider_family = excluded.provider_family,
169	       jsonl_path = excluded.jsonl_path,
170	       fork_point_uuid = excluded.fork_point_uuid`,
171	  ).run(trellisSessionId, newSid, provider, jsonlPath, forkPointUuid);
172	}
173	
174	// 前缀构造核心：在 sourceJsonl 里以 turnUuid（turn-start user entry uuid）为分叉点，
175	// 截出 root→该 turn 末条 assistant 的 uuid 链，改写 sessionId 为新 sid 写同目录
176	// `<newSid>.jsonl`。attached 与 native isolated（per-lineage）两条路共用——前者
177	// 节点 id 即 turn uuid，后者经 nodes.cli_turn_uuid 映射。
178	export function buildPrefixJsonlCore(
179	  sourceJsonlPath: string,
180	  turnUuid: string,
181	): { newSid: string; jsonlPath: string } | null {
182	  const rawLines = readJsonlLines(sourceJsonlPath);
183	  if (!rawLines || rawLines.length === 0) return null;
184	
185	  const tail = terminalAssistantLine(rawLines, turnUuid);
186	  const tailUuid = tail?.entry.uuid;
187	  if (!tail || typeof tailUuid !== "string") return null;
188	
189	  const keepUuids = keepUuidChain(rawLines, tailUuid);
190	  if (!keepUuids) return null;
191	
192	  const newSid = crypto.randomUUID();
193	  const out: string[] = [];
194	  for (const line of rawLines) {
195	    if (line.lineIndex > tail.lineIndex) break;
196	    const uuid = line.entry.uuid;
197	    if (typeof uuid === "string" && !keepUuids.has(uuid)) continue;
198	    const entry: CliRawEntry = { ...line.entry };
199	    if (Object.prototype.hasOwnProperty.call(entry, "sessionId")) {
200	      entry.sessionId = newSid;
201	    }
202	    out.push(JSON.stringify(entry));
203	  }
204	  if (out.length === 0) return null;
205	
206	  const jsonlPath = path.join(path.dirname(sourceJsonlPath), `${newSid}.jsonl`);
207	  fs.writeFileSync(jsonlPath, `${out.join("\n")}\n`, "utf8");
208	  return { newSid, jsonlPath };
209	}
210	
211	export function buildPrefixJsonl(
212	  branchFromNodeId: string,
213	): { newSid: string; jsonlPath: string } | null {
214	  const lineage = attachedLineageForNode(branchFromNodeId);
215	  if (!lineage) return null;
216	  return buildPrefixJsonlCore(lineage.sourceJsonlPath, branchFromNodeId);
217	}
218	
219	// ── native per-lineage（progress/project-lineage-isolation-spec.md）──────────
220	// attachedLineageForNode 的 native 版：origin='native' 的 isolated project 会话里，
221	// lineage 头节点（root / fork 节点）在自己行上持有 claude_session_id，线性子节点
222	// walk-up 解析归属；jsonl 路径由 claudeSessionPath(sid, spawnCwd) 确定性推导，
223	// 不经 cli_lineages（那是 attach-sync 域）。
224	
225	export type NativeLineage = {
226	  lineageSid: string;
227	  jsonlPath: string;
228	  // 该节点的 turn 在 lineage jsonl 里的 uuid（nodes.cli_turn_uuid）。NULL =
229	  // 回填缺失 → 调用方在该点分叉须降级线性 resume。
230	  nodeTurnUuid: string | null;
231	  isJsonlTip: boolean;
232	};
233	
234	export function nativeLineageForNode(
235	  nodeId: string,
236	  spawnCwd: string | null,
237	): NativeLineage | null {
238	  const db = getDB();
239	  const node = db
240	    .prepare(
241	      "SELECT parent_id, claude_session_id, cli_turn_uuid FROM nodes WHERE id = ?",
242	    )
243	    .get(nodeId) as
244	    | {
245	        parent_id: string | null;
246	        claude_session_id: string | null;
247	        cli_turn_uuid: string | null;
248	      }
249	    | undefined;
250	  if (!node) return null;
251	
252	  let lineageSid = node.claude_session_id;
253	  let parentId = node.parent_id;
254	  const parentStmt = db.prepare(
255	    "SELECT parent_id, claude_session_id FROM nodes WHERE id = ?",
256	  );
257	  while (!lineageSid && parentId) {
258	    const parent = parentStmt.get(parentId) as
259	      | { parent_id: string | null; claude_session_id: string | null }
260	      | undefined;
261	    if (!parent) break;
262	    lineageSid = parent.claude_session_id;
263	    parentId = parent.parent_id;
264	  }
265	  if (!lineageSid) return null;
266	
267	  const jsonlPath = claudeSessionPath(lineageSid, spawnCwd);
268	  if (!fs.existsSync(jsonlPath)) return null;
269	  const tipId = newestTurnId(jsonlPath);
270	  return {
271	    lineageSid,
272	    jsonlPath,
273	    nodeTurnUuid: node.cli_turn_uuid,
274	    isJsonlTip: node.cli_turn_uuid !== null && tipId === node.cli_turn_uuid,
275	  };
276	}
277	
278	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
279	
280	// done 后回填该 native isolated 节点的 turn uuid（run-bus 钩子，best-effort）。
281	// jsonl 落盘略滞后于 done 事件（与 reconcileAttachedTurn 同时序）→ 轮询 ≤8×300ms。
282	// 防错配闸：最新 turn 的 question 必须包含节点 question（project prompt = 原文或
283	// anchor 包裹原文，contains 恒成立；skill 命令轮会被解析器滤成噪音则匹配不上）——
284	// 匹配不上就放弃：错误的 uuid 会让分叉切错位置，缺失只是降级线性，后者严格更安全。
285	export async function backfillNativeTurnUuid(nodeId: string): Promise<void> {
286	  const db = getDB();
287	  const row = db
288	    .prepare(
289	      `SELECT n.question, n.cli_turn_uuid, s.origin, s.context_mode AS mode,
290	              s.workspace_path AS wp, s.lineage_isolation AS iso
291	       FROM nodes n JOIN sessions s ON s.id = n.session_id
292	       WHERE n.id = ?`,
293	    )
294	    .get(nodeId) as
295	    | {
296	        question: string;
297	        cli_turn_uuid: string | null;
298	        origin: string;
299	        mode: string;
300	        wp: string | null;
301	        iso: number;
302	      }
303	    | undefined;
304	  if (
305	    !row ||
306	    row.cli_turn_uuid !== null ||
307	    row.origin !== "native" ||
308	    row.mode !== "project" ||
309	    row.iso !== 1
310	  ) {
311	    return;
312	  }
313	
314	  const q = row.question.trim();
315	  for (let i = 0; i < 8; i++) {
316	    // project 的 spawnCwd 恒 = workspace_path（sessionCwd 只对 chat 改道 scratch）。
317	    const lin = nativeLineageForNode(nodeId, row.wp);
318	    if (lin) {
319	      const parsed = parseCliSessionJsonl(lin.jsonlPath);
320	      if (parsed && parsed.turns.length > 0) {
321	        const newest = [...parsed.turns].sort(
322	          (a, b) => b.createdAt - a.createdAt || b.id.localeCompare(a.id),
323	        )[0];
324	        if (!q || newest.question.includes(q)) {
325	          db.prepare(
326	            "UPDATE nodes SET cli_turn_uuid = ? WHERE id = ? AND cli_turn_uuid IS NULL",
327	          ).run(newest.id, nodeId);
328	          return;
329	        }
330	      }
331	    }
332	    await sleep(300);
333	  }
334	}
