1	// CLI session jsonl 的**共享**读取与 turn 归属原语（纯函数，无 DB / 无 server-only）。
2	//
3	// 存在的理由是一次真实的漂移事故：cli-import.ts（把 jsonl 解析成节点树）和
4	// cli-fork.ts（在某个 turn 上截前缀 jsonl 造分叉）各自抄了一份 turn-start 判据，
5	// 之后 import 那份在实测修 bug 时长出了 5 道结构闸（isMeta / promptSource /
6	// interruptedMessageId / isCompactSummary / isVisibleInTranscriptOnly），fork 那份
7	// 一道没跟。两边对「一个 turn 从哪开始」的答案就此分家，而 fork 的入参 turnUuid
8	// **正是 import 定的节点 id** —— 判据不同 = fork 在一条自己认不出的 turn 上截前缀。
9	//
10	// 2026-08-01 实测（889 个 jsonl / 1897 个有回答的 turn）：老判据下 36 个 turn
11	// （1.90%）根本找不到 tail（分叉静默降级成线性），另有 315 个（16.61%）选出的 tail
12	// 与 import 的归属不是同一条 —— 前缀被截在一个**没说完的回答**中间。
13	//
14	// 所以这两侧必须走同一份实现。执行者是编译器（两边都从这里 import），不是注释；
15	// 一致性由 scripts/test-cli-jsonl.ts 在真 jsonl 上回归。
16	import fs from "node:fs";
17	
18	// ── jsonl entry 形状（只声明用到的字段，其余忽略）────────────────────────────
19	
20	export type CliContentBlock = {
21	  type: string;
22	  text?: string;
23	  thinking?: string;
24	  // tool_use
25	  id?: string;
26	  name?: string;
27	  input?: unknown;
28	  // tool_result
29	  tool_use_id?: string;
30	  content?: unknown;
31	  is_error?: boolean;
32	};
33	
34	export type CliUsage = {
35	  input_tokens?: number;
36	  output_tokens?: number;
37	  cache_read_input_tokens?: number;
38	  cache_creation_input_tokens?: number;
39	};
40	
41	export type CliRawEntry = {
42	  type: string;
43	  uuid?: string;
44	  parentUuid?: string | null;
45	  isSidechain?: boolean;
46	  // CLI 注入标记（skill 引导语 / Stop hook 通知 / "Continue from where you
47	  // left off." 等）。真用户输入从不带它 —— 见 isTurnStart。
48	  isMeta?: boolean;
49	  // 这条 user 消息从哪来："typed"(键入) / "sdk" / "queued" 都是真用户；
50	  // "system" 是 CLI 自己投递的（task-notification）。
51	  promptSource?: string;
52	  // 用户按 Esc 打断时 CLI 补的占位消息（"[Request interrupted by user]"）。
53	  // 它指向被打断的那条 assistant 消息，不带 isMeta / promptSource。
54	  interruptedMessageId?: string;
55	  // /compact 之后 CLI 注入的历史摘要（"This session is being continued from…"）。
56	  isCompactSummary?: boolean;
57	  isVisibleInTranscriptOnly?: boolean;
58	  timestamp?: string;
59	  cwd?: string;
60	  gitBranch?: string;
61	  sessionId?: string;
62	  aiTitle?: string;
63	  toolUseResult?: { stderr?: string; stdout?: string } | unknown;
64	  message?: {
65	    role?: string;
66	    content?: string | CliContentBlock[];
67	    usage?: CliUsage;
68	  };
69	};
70	
71	// 带原始行号的 entry —— 截前缀时要按文件顺序切，行号不能丢。
72	export type CliRawLine = {
73	  lineIndex: number;
74	  entry: CliRawEntry;
75	};
76	
77	// ── 基础谓词 ────────────────────────────────────────────────────────────────
78	
79	export function ms(ts: string | undefined): number {
80	  if (!ts) return 0;
81	  const t = Date.parse(ts);
82	  return Number.isNaN(t) ? 0 : t;
83	}
84	
85	export function userText(e: CliRawEntry): string | null {
86	  const c = e.message?.content;
87	  if (typeof c === "string") return c;
88	  if (Array.isArray(c)) {
89	    const texts = c
90	      .filter((b) => b.type === "text" && typeof b.text === "string")
91	      .map((b) => b.text as string);
92	    if (texts.length) return texts.join("\n");
93	  }
94	  return null;
95	}
96	
97	export function isToolResultEntry(e: CliRawEntry): boolean {
98	  const c = e.message?.content;
99	  return Array.isArray(c) && c.some((b) => b.type === "tool_result");
100	}
101	
102	// CLI 注入的命令/系统行不是真用户提问 —— 过滤掉。
103	export function isCommandNoise(text: string): boolean {
104	  const t = text.trimStart();
105	  return (
106	    t.startsWith("<command-name>") ||
107	    t.startsWith("<command-message>") ||
108	    t.startsWith("<local-command-") ||
109	    t.startsWith("<bash-input>") ||
110	    t.startsWith("<bash-stdout>") ||
111	    t.startsWith("Caveat:")
112	  );
113	}
114	
115	// 一个 turn 由「真·用户提问」开启。判定的难点全在于：CLI 会往对话流里塞一堆
116	// 长得和用户提问一模一样的 user 文本消息（skill 触发时的 "Base directory for
117	// this skill: …"、后台 agent 完成的 <task-notification>、Stop hook 的反馈、
118	// "Continue from where you left off."）。把它们误判成 turn-start 的后果不是多
119	// 一个节点那么轻——它会把**后续 assistant 的最终回复整段劫走**挂到假 turn 上，
120	// 真 turn 只剩工具调用、response 为空，UI 里就是一条永远「正在生成…」的僵尸。
121	// 本机 337 个 turn 实测：修前 45 条空 response 带工具，其中 44 条是这么来的。
122	//
123	// 判据用结构字段、不用文本前缀白名单（前缀会随 CLI 版本漂）：
124	//   isMeta === true          —— 83 条注入全中，257 条真用户零误杀
125	//   promptSource === "system" —— task-notification 专属；真用户是 typed/sdk/queued
126	//   interruptedMessageId      —— Esc 打断的占位消息（全库 522 条），这两个字段都没有
127	//   isCompactSummary / isVisibleInTranscriptOnly —— /compact 注入的历史摘要
128	// isCommandNoise 的文本闸留作老版本 jsonl 的兜底（那时还没有这些字段）。
129	export function isTurnStart(e: CliRawEntry): boolean {
130	  if (e.type !== "user") return false;
131	  if (isToolResultEntry(e)) return false;
132	  if (e.isMeta === true) return false;
133	  if (e.promptSource === "system") return false;
134	  if (e.interruptedMessageId !== undefined) return false;
135	  if (e.isCompactSummary === true) return false;
136	  if (e.isVisibleInTranscriptOnly === true) return false;
137	  const text = userText(e);
138	  if (!text || !text.trim()) return false;
139	  if (isCommandNoise(text)) return false;
140	  return true;
141	}
142	
143	// 宽松判据：任何带文本的非 tool_result user 消息都能当 turn-start（含被严格
144	// 判据挡掉的 meta / system / 命令噪声）。只用于严格判据找不到主时的兜底。
145	export function looseTurnStart(e: CliRawEntry): boolean {
146	  return (
147	    e.type === "user" && !isToolResultEntry(e) && Boolean(userText(e)?.trim())
148	  );
149	}
150	
151	// ── turn 归属 ───────────────────────────────────────────────────────────────
152	
153	// byUuid 必须收**全部**带 uuid 的 entry（含 type:"system" 的 compact/边界标记）——
154	// CLI 在每个 turn 之间插 system 节点承载父链，过滤掉会把链打断、让每个 turn
155	// 变成孤根。ownerTurn 上溯时需穿过这些非对话节点继续走。
156	export function indexByUuid(
157	  entries: Iterable<CliRawEntry>,
158	): Map<string, CliRawEntry> {
159	  const byUuid = new Map<string, CliRawEntry>();
160	  for (const e of entries) if (typeof e.uuid === "string") byUuid.set(e.uuid, e);
161	  return byUuid;
162	}
163	
164	// 每条 entry 归属哪个 turn-start（沿 parentUuid 上溯到最近的 turn-start）。
165	// 同一套上溯按不同判据跑两遍 —— 见 makeTurnOwnership 的取舍。
166	export function makeOwnerResolver(
167	  byUuid: Map<string, CliRawEntry>,
168	  isStart: (e: CliRawEntry) => boolean,
169	) {
170	  const turnOf = new Map<string, string | null>();
171	  return function ownerTurn(uuid: string): string | null {
172	    const cached = turnOf.get(uuid);
173	    if (cached !== undefined) return cached;
174	    const e = byUuid.get(uuid);
175	    if (!e) {
176	      turnOf.set(uuid, null);
177	      return null;
178	    }
179	    // 占位防环（坏 jsonl 自指）。
180	    turnOf.set(uuid, null);
181	    let owner: string | null;
182	    if (isStart(e)) owner = e.uuid as string;
183	    else owner = e.parentUuid ? ownerTurn(e.parentUuid) : null;
184	    turnOf.set(uuid, owner);
185	    return owner;
186	  };
187	}
188	
189	export type TurnOwnership = {
190	  // 严格优先、宽松兜底的归属解析。
191	  resolveOwner: (uuid: string) => string | null;
192	  // 被宽松判据认领出来的兜底起点（import 侧要把它们一并组装成节点）。
193	  fallbackStartIds: Set<string>;
194	};
195	
196	// 兜底承载：`claude --continue` / fork 出来的 jsonl，开头可能压根没有真用户
197	// 提问（链头是 "Continue from where you left off." 这类 meta，甚至直接是
198	// assistant 片段）。严格判据下这些链上溯不到任何 turn-start，整段回复会被
199	// **静默丢弃** —— 本机实测 117 条消息 / 16030 字符。所以严格找不到主时退一步
200	// 用宽松判据认领，让内容有处可去。
201	//
202	// 次序不能反：先严格、后宽松。反过来 meta 消息就会重新抢走已经有主的 turn 的
203	// 文本 —— 那正是这套判据当初要修的 bug 本身。
204	export function makeTurnOwnership(
205	  byUuid: Map<string, CliRawEntry>,
206	): TurnOwnership {
207	  const strictOwner = makeOwnerResolver(byUuid, isTurnStart);
208	  const looseOwner = makeOwnerResolver(byUuid, looseTurnStart);
209	  const fallbackStartIds = new Set<string>();
210	  function resolveOwner(uuid: string): string | null {
211	    const strict = strictOwner(uuid);
212	    if (strict) return strict;
213	    const loose = looseOwner(uuid);
214	    if (loose) fallbackStartIds.add(loose);
215	    return loose;
216	  }
217	  return { resolveOwner, fallbackStartIds };
218	}
219	
220	// ── 带行号的整文件读取（截前缀用）──────────────────────────────────────────
221	
222	// 与 cli-import 的宽容读取不同：这里任何一行 JSON 坏掉就整体放弃。截前缀是要
223	// **原样复制**这些行去造一个新会话，读漏一行等于造出一个内容缺失的 lineage，
224	// 宁可不分叉（调用方降级线性 resume）也不能造错。
225	export function readJsonlLines(jsonlPath: string): CliRawLine[] | null {
226	  let raw: string;
227	  try {
228	    raw = fs.readFileSync(jsonlPath, "utf8");
229	  } catch {
230	    return null;
231	  }
232	  const out: CliRawLine[] = [];
233	  const lines = raw.split("\n");
234	  for (let i = 0; i < lines.length; i++) {
235	    const line = lines[i];
236	    if (!line.trim()) continue;
237	    try {
238	      out.push({ lineIndex: i, entry: JSON.parse(line) as CliRawEntry });
239	    } catch {
240	      return null;
241	    }
242	  }
243	  return out;
244	}
245	
246	// 某个 turn 的**末条** assistant 行 —— 前缀 jsonl 切到这里为止。
247	// turnId 是 import 定的节点 id（= turn-start entry 的 uuid），所以归属判据必须
248	// 和 import 用同一套，否则切点会落在别的 turn 里或干脆找不到。
249	export function terminalAssistantLine(
250	  rawLines: CliRawLine[],
251	  turnId: string,
252	): CliRawLine | null {
253	  const byUuid = indexByUuid(rawLines.map((l) => l.entry));
254	  const { resolveOwner } = makeTurnOwnership(byUuid);
255	
256	  function depth(uuid: string): number {
257	    const seen = new Set<string>();
258	    let cur: string | null | undefined = uuid;
259	    let n = 0;
260	    while (cur && !seen.has(cur)) {
261	      seen.add(cur);
262	      n++;
263	      cur = byUuid.get(cur)?.parentUuid;
264	    }
265	    return n;
266	  }
267	
268	  let best: CliRawLine | null = null;
269	  for (const line of rawLines) {
270	    const uuid = line.entry.uuid;
271	    if (
272	      typeof uuid !== "string" ||
273	      line.entry.type !== "assistant" ||
274	      line.entry.isSidechain === true ||
275	      resolveOwner(uuid) !== turnId
276	    ) {
277	      continue;
278	    }
279	    if (!best) {
280	      best = line;
281	      continue;
282	    }
283	    const d = depth(uuid);
284	    const bd = depth(best.entry.uuid as string);
285	    if (
286	      d > bd ||
287	      (d === bd && ms(line.entry.timestamp) > ms(best.entry.timestamp)) ||
288	      (d === bd &&
289	        ms(line.entry.timestamp) === ms(best.entry.timestamp) &&
290	        line.lineIndex > best.lineIndex)
291	    ) {
292	      best = line;
293	    }
294	  }
295	  return best;
296	}
297	
298	// 从 tailUuid 沿 parentUuid 一路上溯收集要保留的 uuid 集合。自指/成环返回 null。
299	export function keepUuidChain(
300	  rawLines: CliRawLine[],
301	  tailUuid: string,
302	): Set<string> | null {
303	  const byUuid = indexByUuid(rawLines.map((l) => l.entry));
304	  const keep = new Set<string>();
305	  let cur: string | null | undefined = tailUuid;
306	  while (cur) {
307	    if (keep.has(cur)) return null;
308	    keep.add(cur);
309	    cur = byUuid.get(cur)?.parentUuid;
310	  }
311	  return keep;
312	}
313

