220	// attachedLineageForNode 的 native 版：origin='native' 的 isolated project 会话里，
221	// lineage 头节点（root / fork 节点）在自己行上持有 claude_session_id，线性子节点
222	// walk-up 解析归属；jsonl 路径由 claudeSessionPath(sid, spawnCwd) 确定性推导，
223	// 不经 cli_lineages（那是 attach-sync 域）。
224	
225	export type NativeLineage = {
226	  lineageSid: string;
227	  jsonlPath: string;
228	  // 该节点的 turn 在 lineage jsonl 里的 uuid（nodes.cli_turn_uuid）。NULL =
229	  // 回填缺失 → 调用方在该点分叉须降级线性 resume。
230	  nodeTurnUuid: string | null;
231	  isJsonlTip: boolean;
232	};
233	
234	export function nativeLineageForNode(
235	  nodeId: string,
236	  spawnCwd: string | null,
237	): NativeLineage | null {
238	  const db = getDB();
239	  const node = db
240	    .prepare(
241	      "SELECT parent_id, claude_session_id, cli_turn_uuid FROM nodes WHERE id = ?",
242	    )
243	    .get(nodeId) as
244	    | {
245	        parent_id: string | null;
246	        claude_session_id: string | null;
247	        cli_turn_uuid: string | null;
248	      }
249	    | undefined;
250	  if (!node) return null;
251	
252	  let lineageSid = node.claude_session_id;
253	  let parentId = node.parent_id;
254	  const parentStmt = db.prepare(
255	    "SELECT parent_id, claude_session_id FROM nodes WHERE id = ?",
256	  );
257	  while (!lineageSid && parentId) {
258	    const parent = parentStmt.get(parentId) as
259	      | { parent_id: string | null; claude_session_id: string | null }
260	      | undefined;
261	    if (!parent) break;
262	    lineageSid = parent.claude_session_id;
263	    parentId = parent.parent_id;
264	  }
265	  if (!lineageSid) return null;
266	
267	  const jsonlPath = claudeSessionPath(lineageSid, spawnCwd);
268	  if (!fs.existsSync(jsonlPath)) return null;
269	  const tipId = newestTurnId(jsonlPath);
270	  return {
271	    lineageSid,
272	    jsonlPath,
273	    nodeTurnUuid: node.cli_turn_uuid,
274	    isJsonlTip: node.cli_turn_uuid !== null && tipId === node.cli_turn_uuid,
275	  };
276	}
277	
278	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
279	
280	// done 后回填该 native isolated 节点的 turn uuid（run-bus 钩子，best-effort）。
281	// jsonl 落盘略滞后于 done 事件（与 reconcileAttachedTurn 同时序）→ 轮询 ≤8×300ms。
282	// 防错配闸：最新 turn 的 question 必须包含节点 question（project prompt = 原文或
283	// anchor 包裹原文，contains 恒成立；skill 命令轮会被解析器滤成噪音则匹配不上）——
284	// 匹配不上就放弃：错误的 uuid 会让分叉切错位置，缺失只是降级线性，后者严格更安全。
285	export async function backfillNativeTurnUuid(nodeId: string): Promise<void> {
286	  const db = getDB();
287	  const row = db
288	    .prepare(
289	      `SELECT n.question, n.cli_turn_uuid, s.origin, s.context_mode AS mode,
290	              s.workspace_path AS wp, s.lineage_isolation AS iso
291	       FROM nodes n JOIN sessions s ON s.id = n.session_id
292	       WHERE n.id = ?`,
293	    )
294	    .get(nodeId) as
295	    | {
296	        question: string;
297	        cli_turn_uuid: string | null;
298	        origin: string;
299	        mode: string;
300	        wp: string | null;
301	        iso: number;
302	      }
303	    | undefined;
304	  if (
305	    !row ||
306	    row.cli_turn_uuid !== null ||
307	    row.origin !== "native" ||
308	    row.mode !== "project" ||
309	    row.iso !== 1
310	  ) {
311	    return;
312	  }
313	
314	  const q = row.question.trim();
315	  for (let i = 0; i < 8; i++) {
316	    // project 的 spawnCwd 恒 = workspace_path（sessionCwd 只对 chat 改道 scratch）。
317	    const lin = nativeLineageForNode(nodeId, row.wp);
318	    if (lin) {
319	      const parsed = parseCliSessionJsonl(lin.jsonlPath);
320	      if (parsed && parsed.turns.length > 0) {
321	        const newest = [...parsed.turns].sort(
322	          (a, b) => b.createdAt - a.createdAt || b.id.localeCompare(a.id),
323	        )[0];
324	        if (!q || newest.question.includes(q)) {
325	          db.prepare(
326	            "UPDATE nodes SET cli_turn_uuid = ? WHERE id = ? AND cli_turn_uuid IS NULL",
327	          ).run(newest.id, nodeId);
328	          return;
329	        }
330	      }
331	    }
332	    await sleep(300);
333	  }
334	}
335

